using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Security.Cryptography;
using GdUnit4;
using Refii.Textures;
using static GdUnit4.Assertions;

namespace Refii.Tests;

/// <summary>The transcoder's exact bytes on every path. These are the pixels the phone uploads, and a
/// speed-up must not move them.</summary>
/// <remarks>The hex and the hashes were generated by the transcoder as it was before its fast paths
/// (<c>FourColour</c>, the flat block, the uniform alpha shortcut), so passing here means old and new
/// agree. A change that means to alter the output replaces them on purpose.</remarks>
[TestSuite]
public sealed class AstcTranscodeGoldenTests
{
    private const int ModeQuant4 = 0x042, ModeQuant4Dual = 0x442, ModeQuant3 = 0x051;
    private const int CemRgb = 8, CemRgba = 12;
    private const int BlocksPerPath = 20000;

    /// <summary>A small generator of its own, so no runtime's Random can move the pinned hashes.</summary>
    private sealed class Blocks
    {
        private ulong _state;

        public Blocks(ulong seed) => _state = seed;

        public ulong Next()
        {
            _state ^= _state << 13;
            _state ^= _state >> 7;
            _state ^= _state << 17;
            return _state;
        }

        public int Below(int limit) => (int)(Next() % (ulong)limit);

        public int Colour() => Below(6) switch
        {
            0 => 0,
            1 => 0xFFFF,
            2 => Below(32) << 11,
            3 => Below(64) << 5,
            4 => Below(32),
            _ => Below(65536),
        };

        public uint Indices() => Below(5) switch
        {
            0 => 0,
            1 => 0xFFFFFFFF,
            2 => 0x55555555,
            3 => 0xAAAAAAAA,
            _ => (uint)Next(),
        };
    }

    /// <summary>Sum of a 5:6:5 colour's expanded channels: the ASTC decoder's endpoint-order test.</summary>
    private static int Sum(int c)
    {
        int r = (c >> 11) & 31, g = (c >> 5) & 63, b = c & 31;
        return ((r << 3) | (r >> 2)) + ((g << 2) | (g >> 4)) + ((b << 3) | (b >> 2));
    }

    private static void Colours(Span<byte> block, int c0, int c1, uint indices)
    {
        BinaryPrimitives.WriteUInt16LittleEndian(block, (ushort)c0);
        BinaryPrimitives.WriteUInt16LittleEndian(block[2..], (ushort)c1);
        BinaryPrimitives.WriteUInt32LittleEndian(block[4..], indices);
    }

    private static void FourColour(Blocks r, Span<byte> block, bool swapped)
    {
        int c0, c1;
        do
        {
            c0 = r.Colour();
            c1 = r.Colour();
            if (c0 < c1) (c0, c1) = (c1, c0);
        }
        while (c0 == c1 || Sum(c1) < Sum(c0) != swapped);
        Colours(block, c0, c1, r.Indices());
    }

    private static void ThreeColour(Blocks r, Span<byte> block)
    {
        int c0, c1;
        uint indices;
        do
        {
            c0 = r.Colour();
            c1 = r.Colour();
            if (c0 > c1) (c0, c1) = (c1, c0);
            indices = r.Indices();
        }
        while (c0 == c1 && indices == 0);
        Colours(block, c0, c1, indices);
    }

    private static void AlphaIndices(Span<byte> block, ulong indices)
    {
        for (int k = 0; k < 6; k++) block[2 + k] = (byte)(indices >> (8 * k));
    }

    /// <summary>Alpha that cannot be uniform: different endpoints, the first texel on the second, the
    /// second on the first, and the rest anywhere.</summary>
    private static void VaryingAlpha(Blocks r, Span<byte> block)
    {
        block[0] = (byte)r.Below(256);
        block[1] = (byte)r.Below(256);
        if (block[0] == block[1]) block[1] ^= 0x80;
        AlphaIndices(block, (r.Next() & 0xFFFFFFFFFFFF & ~0x3Ful) | 1);
    }

    private sealed record PathCase(string Name, bool Bc3, int Mode, int Cem, BlockMaker Make, string Hash);

    private delegate void BlockMaker(Blocks r, Span<byte> block);

    /// <summary>Every path through Bc1Block and Bc3Block, with the block mode each must write.</summary>
    private static readonly PathCase[] Paths =
    {
        new("bc1 four colour", false, ModeQuant4, CemRgb, (r, b) => FourColour(r, b, false),
            "CC1F2CB9BA89A4D0F2D38909DAEEB0F65648ED6EBB5E1B1BD98051067E62A9BC"),
        new("bc1 four colour, swapped endpoints", false, ModeQuant4, CemRgb, (r, b) => FourColour(r, b, true),
            "C6541C79D7F55426ED20A95792BE0D38C7F7ACBA4B7F58CD8ABB93B381E428D1"),
        new("bc1 flat", false, ModeQuant3, CemRgb, (r, b) => { int c = r.Below(65536); Colours(b, c, c, 0); },
            "3B168652AB2FC52B9DFDE12415EB2BB0789F1BB6C6CF4D80D4D47C0AB559A5EE"),
        new("bc1 three colour", false, ModeQuant3, CemRgb, ThreeColour,
            "E8FA93AD6E423CB271039982A2D45CDFBD934FC782EE2FAADDA11A6EFD87B92F"),
        new("bc3 uniform alpha, index 0", true, ModeQuant4, CemRgba, (r, b) =>
            {
                b[0] = (byte)r.Below(256);
                b[1] = (byte)r.Below(256);
                AlphaIndices(b, 0);
                Colours(b[8..], r.Colour(), r.Colour(), r.Indices());
            },
            "F0ABA32DA04670387FEA6C8044867CDBA0BA033F702B625960FA257299466C79"),
        new("bc3 uniform alpha, equal endpoints", true, ModeQuant4, CemRgba, (r, b) =>
            {
                b[0] = b[1] = (byte)r.Below(256);
                ulong indices = 0;
                for (int t = 0; t < 16; t++) indices |= (ulong)r.Below(6) << (3 * t);
                AlphaIndices(b, indices | 1);
                Colours(b[8..], r.Colour(), r.Colour(), r.Indices());
            },
            "1076959CA85584A1BDD790BAE8C9211AB665849CE35A07F5DBCD807DB3FD2D19"),
        new("bc3 uniform alpha, one index", true, ModeQuant4, CemRgba, (r, b) =>
            {
                b[0] = (byte)r.Below(256);
                b[1] = (byte)r.Below(256);
                int index = 1 + r.Below(7);
                ulong indices = 0;
                for (int t = 0; t < 16; t++) indices |= (ulong)index << (3 * t);
                AlphaIndices(b, indices);
                Colours(b[8..], r.Colour(), r.Colour(), r.Indices());
            },
            "2DCE23B1395F49D510F83603BCFF66B6AB0C3EA7D179E7B373E0EF23AAD5C918"),
        new("bc3 varying alpha", true, ModeQuant4Dual, CemRgba, (r, b) =>
            {
                VaryingAlpha(r, b);
                int c0 = r.Colour(), c1 = r.Colour();
                if (Sum(c1) < Sum(c0)) (c0, c1) = (c1, c0);
                Colours(b[8..], c0, c1, r.Indices());
            },
            "F12E900DE7407724AAC4761862CB9A882C36EF7D6180CF25CC29D0C63754C91F"),
        new("bc3 varying alpha, swapped endpoints", true, ModeQuant4Dual, CemRgba, (r, b) =>
            {
                VaryingAlpha(r, b);
                // Far enough apart in brightness that quantizing cannot reorder them.
                int bright = 0xC000 | r.Below(0x4000), dark = r.Below(0x0800);
                Colours(b[8..], bright | 0x07E0, dark & 0x001F, r.Indices());
            },
            "37CB8410FE7FD08B633A90280050BFABD0929C60F18B1986C8018A0D662343D7"),
        new("bc3 cut-out alpha", true, ModeQuant4Dual, CemRgba, (r, b) =>
            {
                b[0] = (byte)r.Below(200);
                b[1] = (byte)(b[0] + r.Below(56));
                ulong indices = 0;
                for (int t = 0; t < 16; t++) indices |= (ulong)(6 + (t == 0 ? 0 : t == 1 ? 1 : r.Below(2))) << (3 * t);
                AlphaIndices(b, indices);
                Colours(b[8..], r.Colour(), r.Colour(), r.Indices());
            },
            "796C68CC721690CFE4A63CC4B884016678E98537D59A2D35407A8194E8775427"),
    };

    /// <summary>Single blocks to read in a failure message: source hex, then the ASTC block.</summary>
    private static readonly (string Name, string Source, string Astc)[] Golden =
    {
        ("bc1 all zero, flat black", "0000000000000000", "51000100000000000000000000000000"),
        ("bc1 white flat", "FFFFFFFF00000000", "5100FFFFFFFFFFFF0100000000000000"),
        ("bc1 mid grey flat", "1084108400000000", "51000909050509090100000000000000"),
        ("bc1 all ones, equal colours, index 3", "FFFFFFFFFFFFFFFF", "5100FFFFFFFFFFFF0100000000000000"),
        ("bc1 grey, all index 3 is black", "10841084FFFFFFFF", "51000909050509090100000000000000"),
        ("bc1 four colour kept, red to cyan", "00F8FF07E4E4E4E4", "4200FF0100FE01FE0100000039393939"),
        ("bc1 four colour swapped, white to black", "FFFF00001B1B1B1B", "420001FE01FE01FE0100000093939393"),
        ("bc1 four colour swapped, magenta to green", "1FF8E0070123ABCD", "420001FEFF0100FE010000002E95B73F"),
        ("bc1 three colour kept", "0000FFFF1B1B1B1B", "510001FE01FE01FE01000000004791C8"),
        ("bc1 three colour swapped, cyan to red", "FF0700F8E4E4E4E4", "5100FF0100FE01FE0100000080E92A4F"),
        ("bc1 three colour, black nearest the middle", "1F00E0FFFFFFFFFF", "510001FE01FEFF010000000080ADADAD"),
        ("bc3 all zero", "00000000000000000000000000000000", "42800100000000000000000000000000"),
        ("bc3 opaque, index 0", "FFFF000000000000FFFF000000000000", "428001FE01FE01FEFFFF0100FFFFFFFF"),
        ("bc3 half alpha, index 0, colour order c0 < c1", "80400000000000000000FFFF1B1B1B1B", "428001FE01FE01FE010101006C6C6C6C"),
        ("bc3 equal endpoints, mixed low indices", "7777D1584463118DFFFF00001B1B1B1B", "428001FE01FE01FEEFEE000093939393"),
        ("bc3 uniform on an interpolant", "F010922449922449E0071F00E4E4E4E4", "42800100FE0100FEA1A1010039393939"),
        ("bc3 all texels 255 by index 7", "1020FFFFFFFFFFFF00F8FF071B1B1B1B", "4280FF0100FE01FEFFFF01006C6C6C6C"),
        ("bc3 cut-out, 0 and 255", "0A14BEEFFBBEEFFB00F8FF07E4E4E4E4", "42840300042000C2870F870F870F870F"),
        ("bc3 gradient alpha, colours kept", "FF0088C6FA88C6FAE0071F00E4E4E4E4", "42840120002010C6A41EB53CA41EB53C"),
        ("bc3 gradient alpha, colours swapped", "FF0088C6FA88C6FAFFFF000027272727", "42848100042018C45FA14E835FA14E83"),
        ("bc3 flat colour, varying alpha", "20C0FFFFFF0000001084108400000000", "4284DFFFFFEF25C20000000033333333"),
    };

    private static byte[] Source(string hex) => Convert.FromHexString(hex);

    private static byte[] PathPayload(PathCase path)
    {
        int size = path.Bc3 ? 16 : 8;
        var payload = new byte[BlocksPerPath * size];
        var random = new Blocks(0x9E3779B97F4A7C15ul ^ (ulong)path.Name.Length * 0x100000001B3ul);
        for (int i = 0; i < BlocksPerPath; i++) path.Make(random, payload.AsSpan(i * size, size));
        return payload;
    }

    /// <summary>The whole-output hash of each path, named, so a failure says which path moved.</summary>
    [TestCase]
    public void EveryPathKeepsItsPinnedHash()
    {
        var expected = new List<string>();
        var actual = new List<string>();
        foreach (PathCase path in Paths)
        {
            byte[] source = PathPayload(path);
            var astc = new byte[BlocksPerPath * 16];
            AssertThat(Engine_AstcTranscode.Transcode(source, path.Bc3, astc)).IsTrue();
            expected.Add($"{path.Name}: {path.Hash}");
            actual.Add($"{path.Name}: {Convert.ToHexString(SHA256.HashData(astc))}");
        }

        AssertThat(string.Join("\n", actual)).IsEqual(string.Join("\n", expected));
    }

    /// <summary>The pinned blocks really take the path they are named for: otherwise a hash pins
    /// nothing about it.</summary>
    [TestCase]
    public void EveryPathWritesItsBlockMode()
    {
        Span<byte> rgba = stackalloc byte[64];
        foreach (PathCase path in Paths)
        {
            byte[] source = PathPayload(path);
            var astc = new byte[BlocksPerPath * 16];
            Engine_AstcTranscode.Transcode(source, path.Bc3, astc);
            int wrong = 0;
            for (int i = 0; i < BlocksPerPath; i++)
            {
                ReadOnlySpan<byte> block = astc.AsSpan(i * 16, 16);
                ushort low = BinaryPrimitives.ReadUInt16LittleEndian(block);
                int mode = low & 0x7FF;
                int cem = (BinaryPrimitives.ReadInt32LittleEndian(block) >> 13) & 15;
                if (mode != path.Mode || cem != path.Cem) wrong++;

                // Throws on an endpoint order the decoder would read as blue contraction.
                Engine_AstcTranscode.DecodeForTests(block, rgba);
            }

            AssertThat($"{path.Name}: {wrong}").IsEqual($"{path.Name}: 0");
        }
    }

    /// <summary>Block by block and whole payload give the same bytes, on all paths in one payload.</summary>
    [TestCase]
    public void TheBlockCallsAgreeWithAWholePayload()
    {
        Span<byte> one = stackalloc byte[16];
        foreach (bool bc3 in new[] { false, true })
        {
            int size = bc3 ? 16 : 8;
            byte[] source = Paths.Where(p => p.Bc3 == bc3).SelectMany(PathPayload).ToArray();
            int blocks = source.Length / size;
            var whole = new byte[blocks * 16];
            AssertThat(Engine_AstcTranscode.Transcode(source, bc3, whole)).IsTrue();
            int different = 0;
            for (int i = 0; i < blocks; i++)
            {
                if (bc3) Engine_AstcTranscode.Bc3Block(source.AsSpan(i * size, size), one);
                else Engine_AstcTranscode.Bc1Block(source.AsSpan(i * size, size), one);
                if (!one.SequenceEqual(whole.AsSpan(i * 16, 16))) different++;
            }

            AssertThat(different).IsEqual(0);
        }
    }

    [TestCase]
    public void GoldenBlocksAreExact()
    {
        var expected = new List<string>();
        var actual = new List<string>();
        Span<byte> astc = stackalloc byte[16];
        foreach ((string name, string hex, string golden) in Golden)
        {
            byte[] source = Source(hex);
            // Whatever the output held must not show through.
            astc.Fill(0xCC);
            if (source.Length == 16) Engine_AstcTranscode.Bc3Block(source, astc);
            else Engine_AstcTranscode.Bc1Block(source, astc);
            expected.Add($"{name}: {golden}");
            actual.Add($"{name}: {Convert.ToHexString(astc)}");
        }

        AssertThat(string.Join("\n", actual)).IsEqual(string.Join("\n", expected));
    }

    /// <summary>The class skips zeroing its locals, so nothing may read one before writing it: a block
    /// transcoded on a stack full of rubbish comes out the same.</summary>
    [TestCase]
    public void DirtyStackDoesNotReachTheOutput()
    {
        foreach (PathCase path in Paths)
        {
            int size = path.Bc3 ? 16 : 8;
            byte[] source = PathPayload(path);
            var clean = new byte[BlocksPerPath * 16];
            Engine_AstcTranscode.Transcode(source, path.Bc3, clean);
            int different = 0;
            for (int i = 0; i < BlocksPerPath; i += 50)
            {
                foreach (byte rubbish in new byte[] { 0x00, 0xA5, 0xFF })
                    if (!TranscodeOnDirtyStack(source.AsSpan(i * size, size), path.Bc3, rubbish, clean.AsSpan(i * 16, 16)))
                        different++;
            }

            AssertThat($"{path.Name}: {different}").IsEqual($"{path.Name}: 0");
        }
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static bool TranscodeOnDirtyStack(ReadOnlySpan<byte> source, bool bc3, byte rubbish, ReadOnlySpan<byte> expected)
    {
        Dirty(rubbish);
        Span<byte> astc = stackalloc byte[16];
        if (bc3) Engine_AstcTranscode.Bc3Block(source, astc);
        else Engine_AstcTranscode.Bc1Block(source, astc);
        return astc.SequenceEqual(expected);
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static void Dirty(byte rubbish)
    {
        Span<byte> stack = stackalloc byte[8192];
        stack.Fill(rubbish);
        GC.KeepAlive(stack[100]);
    }
}
